SELECT COUNT(*) AS employee_count, SUM(e.sal) AS total_sal, MAX(d.name) AS maximum_dept_name
FROM emp e JOIN dept d ON e.deptno = d.deptno
WHERE e.comm = 17;

SELECT COUNT(DISTINCT e.deptno) AS distinct_depts, SUM(DISTINCT e.comm) AS distinct_comm_sum, MAX(e.sal) AS maximum_sal
FROM emp e JOIN dept d ON e.deptno = d.deptno
WHERE e.mgr = 23058651;

SELECT COUNT(DISTINCT en.job) AS distinct_jobs, SUM(en.sal) AS total_sal, MAX(d.name) AS maximum_dept_name
FROM empnullables en JOIN dept d ON en.deptno = d.deptno
WHERE en.mgr = 23058651;

SELECT COUNT(*) AS employee_count, SUM(e.sal) AS total_sal, MAX(e.comm) AS maximum_comm
FROM emp e
WHERE e.empno BETWEEN 100000 AND 199999;

SELECT COUNT(*) AS employee_count, SUM(e.comm) AS total_comm, MAX(e.sal) AS maximum_sal
FROM emp e
WHERE e.sal BETWEEN 1000 AND 1100;
